"theorem matrix_action_{count} {context_binders}{{params : {parameter_type}}} {{{index_names} : Nat}}
    {{input ideal : ExactMatrix {q} {n} {rows} {inner}}}
    {{action : ErrorMatrix {n} {inner} {columns}}}
    {{output : ExactMatrix {q} {n} {rows} {columns}}} {{bound gain : Nat}}
    (runs : {relation} {context_arguments}params {index_names} {inputs} output)
    (close : Approx input ideal bound) (actionBound : ActionGain action gain) :
    Approx output (ideal * ({action})) (gain * bound) := by
  have equation : output = input * ({action}) := runs
  rw [equation]
  exact approximate_right_action (by decide) close actionBound

"

"theorem matrix_action_family_{count} {context_binders}{{params : {parameter_type}}} {outer_binders} {{lanes : Nat}}
    {{input ideal : Fin lanes → ExactMatrix {q} {n} {rows} {inner}}}
    {{action : Fin lanes → ErrorMatrix {n} {inner} {columns}}}
    {{output : Fin lanes → ExactMatrix {q} {n} {rows} {columns}}} {{bound gain : Fin lanes → Nat}}
    (runs : ∀ i : Fin lanes, {relation} {context_arguments}params {outer_indices} i.val {family_inputs} (output i))
    (close : ∀ i, Approx (input i) (ideal i) (bound i))
    (actionBound : ∀ i, ActionGain (action i) (gain i)) :
    ∀ i, Approx (output i) (ideal i * ({family_action})) (gain i * bound i) := by
  intro i
  exact matrix_action_{count} (runs i) (close i) (actionBound i)

"

"theorem matrix_action_family_sum_{count} {context_binders}{{params : {parameter_type}}} {outer_binders} {{lanes : Nat}}
    {{input ideal : Fin lanes → ExactMatrix {q} {n} {rows} {inner}}}
    {{action : Fin lanes → ErrorMatrix {n} {inner} {columns}}}
    {{output : Fin lanes → ExactMatrix {q} {n} {rows} {columns}}} {{bound gain : Fin lanes → Nat}}
    (runs : ∀ i : Fin lanes, {relation} {context_arguments}params {outer_indices} i.val {family_inputs} (output i))
    (close : ∀ i, Approx (input i) (ideal i) (bound i))
    (actionBound : ∀ i, ActionGain (action i) (gain i)) :
    Approx (Finset.univ.sum output)
      (Finset.univ.sum (fun i => ideal i * ({family_action})))
      (Finset.univ.sum (fun i => gain i * bound i)) := by
  exact family_approximate_sum Finset.univ output _ _ (fun i _ => matrix_action_{count} (runs i) (close i) (actionBound i))

"

"theorem private_encoding_scope_{count} {context_binders}{{params : {parameter_type}}} {{{index_names} : Nat}}
    {{secret inputBound helperBound gain : Nat}}
    {{input output : ExactMatrix {q} {n} 1 {columns}}}
    {{mask : ExactMatrix {q} {n} 1 secret}} {{publicKey : ExactMatrix {q} {n} secret {columns}}}
    {{payloadGadget : ExactMatrix {q} {n} 1 {columns}}}
    {{message rhsMessage : ExactPoly {q} {n}}} {{messageInteger : ErrorPoly {n}}}
    {{inputError helperError : ErrorMatrix {n} 1 {columns}}}
    {{action : ErrorMatrix {n} {columns} {columns}}}
    (runs : {relation} {context_arguments}params {index_names} {inputs} output)
    (encodingEquation : input = mask * publicKey - message • payloadGadget + reduceMatrix {q} {n} 1 {columns} inputError)
    (actionEquation : payloadGadget * ({action}) = rhsMessage • payloadGadget + reduceMatrix {q} {n} 1 {columns} helperError)
    (messageLift : message = reducePoly {q} {n} messageInteger)
    (messageBound : polynomialL1 messageInteger ≤ 1)
    (inputBounded : CoeffBound inputError inputBound)
    (helperBounded : CoeffBound helperError helperBound)
    (actionBounded : ActionGain action gain) :
    Approx output (mask * (publicKey * ({action})) - (message * rhsMessage) • payloadGadget)
      (gain * inputBound + helperBound) := by
  have equation : output = input * ({action}) := runs
  rw [equation]
  exact private_encoding_transfer_sampled (by decide) encodingEquation actionEquation messageLift messageBound inputBounded helperBounded actionBounded

"
